<?php if($reviewDocuments):?><div class="table-wrap"><table class="review-table"><thead><tr><th>Document</th><th>Issued</th><th>Expiration</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($reviewDocuments as$document):?><tr><td><strong><?=h($document['document_type'])?></strong><span class="file-name" title="<?=h($document['original_name'])?>"><?=h($document['original_name'])?></span></td><td><?=edDate($document['issue_date'])?></td><td><?=edDate($document['expiry_date'])?></td><td><span class="status">FOR VERIFICATION</span></td><td><div class="actions"><a class="btn btn-light" target="_blank" rel="noopener" href="employee_documents.php?download=<?=(int)$document['id']?>"><i class="fa-solid fa-eye"></i> View</a><?php if($canVerify&&(int)$document['uploaded_by']!==$userId):?><form method="post" class="decision-form"><?=csrfField()?><input type="hidden" name="action" value="verify"><input type="hidden" name="id" value="<?=(int)$document['id']?>"><input type="hidden" name="return_view" value="profile"><input type="hidden" name="return_employee_id" value="<?=(int)$document['employee_id']?>"><button class="btn btn-green" type="submit"><i class="fa-solid fa-check"></i> Verify</button></form><form method="post" class="decision-form"><?=csrfField()?><input type="hidden" name="action" value="reject"><input type="hidden" name="id" value="<?=(int)$document['id']?>"><input type="hidden" name="return_view" value="documents"><input name="verification_remarks" required aria-label="Rejection reason" placeholder="Rejection reason"><button class="btn btn-red" type="submit"><i class="fa-solid fa-xmark"></i> Reject</button></form><?php else:?><span class="status">OWN UPLOAD</span><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty"><i class="fa-solid fa-circle-check"></i>No documents are waiting for verification for this employee.</div><?php endif;?><?php endif;?></div><footer class="review-footer"><a class="btn btn-light" href="employee_documents.php?view=documents">Close</a></footer></section></div><?php if($success):?><div class="verification-success-overlay" data-verification-success><section><i class="fa-solid fa-circle-check"></i><h2>Document Verified</h2><p><?=h($success)?></p><button class="btn btn-green" type="button">OK</button></section></div><script>document.querySelector('[data-verification-success] button').addEventListener('click',()=>document.querySelector('[data-verification-success]').remove());</script><?php endif;?></body></html>
